+        assert!(selection.skips(Phase::Packages));
+        assert!(selection.skips(Phase::FinalHook));
+    }
+
+    #[test]
+    fn resource_kinds_map_to_their_owning_phase() {
+        assert_eq!(Phase::for_resource_kind("directory"), Some(Phase::Files));
+        assert_eq!(
